spec.expr:
sum by (phys) (
  rate(
    windows_gpu_engine_time_seconds_total{
      engtype="Cuda"
    }[5s]
  )
  * on(process_id) group_left(process)
  windows_process_info{
    process="llama-server"
  }
) * 100

sum by (phys, process) (
  windows_gpu_process_memory_dedicated_bytes
  * on(process_id) group_left(process)
  windows_process_info{
    process="llama-server"
  }
) / 1024 / 1024

sum by (phys, engtype) (
  rate(
    windows_gpu_engine_time_seconds_total{
      engtype=~"Cuda"
    }[5s]
  )
) * 100
